\label{th:main_result}
Suppose that $Q$ is a Carleson cube of the upper half-plane near the origin, say $[-r,r]\times[0,r]\subset\overline{\mathbb{H}}$ for some small $r>0$, and $I$ is its intersection with $\mathbb{R}$ (in this case $[-r,r]\subset\mathbb{R}$). With the notations in the previous section and $q=1$, the $(p,q)$-th moment of bulk/boundary quotient of Gaussian multiplicative chaos measures is finite, i.e.
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q)^{p}}{\mu^{\partial}(I)}\right]<\infty
\end{equation*}
if $p<\min(\frac{2}{\gamma^2}+\frac{1}{2},\frac{4}{\gamma^2})$. In particular, $p$ can be strictly greater than $\frac{2}{\gamma^2}$ with this condition.

\label{th:main_result_positive}
Suppose that $Q$ is a Carleson cube of the upper half-plane $\overline{\mathbb{H}}$ near the origin, and $I$ its intersection with $\mathbb{R}$. Suppose that $p,q\geq 0$. Then
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q)^{p}}{\mu^{\partial}(I)^{q}}\right]<\infty
\end{equation*}
if $p<\min(\frac{2}{\gamma^2}+\frac{q}{2},\frac{4}{\gamma^2})$.

\label{lemm:KahaneConvexityInequality}
Let $\Omega\subset\mathbb{R}^{d}$ be a bounded domain, and $X,Y$ are log-correlated Gaussian fields on $\Omega$ with the following covariance comparison inequality:
\begin{equation*}
    \forall x,y\in\Omega,\quad \mathbb{E}[X(x)X(y)]\leq\mathbb{E}[Y(x)Y(y)].
\end{equation*}
Then for any convex functional $F:\mathbb{R}_{\geq 0}\to\mathbb{R}$ with at most polynomial growth at the boundaries,
\begin{equation*}
    \mathbb{E}\left[F\left(\int_{\Omega}e^{X(z)-\frac{1}{2}\mathbb{E}[X(z)^2]}d\sigma(z)\right)\right]\leq\mathbb{E}\left[F\left(\int_{\Omega}e^{Y(z)-\frac{1}{2}\mathbb{E}[Y(z)^2]}d\sigma(z)\right)\right],
\end{equation*}
where $\sigma$ is absolutely continuous with respect to the Lebesgue measure on $\Omega$.

If $G$ is any smooth functional with subgaussian growth at infinity as well as in its first and second derivatives, and if we define
\begin{equation*}
    \varphi(t)\coloneqq\mathbb{E}[G(W_1(t),\dots,W_n(t))],
\end{equation*}
then
\begin{equation}\label{eq:KeyIdentity}
    \varphi'(t)=\frac{1}{2}\sum_{1\leq i,j\leq n}\mathbb{E}[\partial_{ij}G(W_1(t),\dots,W_n(t))W_i(t)W_j(t)](\mathbb{E}[B_iB_j]-\mathbb{E}[A_iA_j]).
\end{equation}

Deriving with respect to $t$, with the chain rule we get
\begin{equation*}
    \varphi'(t)=\sum\limits_{i=1}^{n}\mathbb{E}[W'_i(t)\cdot \partial_i G(W_1(t),\dots,W_n(t))].
\end{equation*}
Since
\begin{equation*}
    W'_i(t)=(Z'_i(t)-\mathbb{E}[Z_i(t)Z'_i(t)])W_i(t),
\end{equation*}
we have
\begin{equation}\label{eq:IntermediateStep}
    \varphi'(t)=\sum\limits_{i=1}^{n}\mathbb{E}[(Z'_i(t)-\mathbb{E}[Z_i(t)Z'_i(t)])W_i(t)\cdot \partial_i G(W_1(t),\dots,W_n(t))].
\end{equation}

We now fix $1\leq i\leq n$ and apply the Gaussian integration by parts formula to the term $Z'_i(t)$. When performing the Gaussian integration by parts, the Gaussian variable $Z'_i(t)$ should contract with all other Gaussians in the expression above.

$\bullet$ When the other Gaussian variable in the Gaussian integration by parts formula is $W_i(t)$, for each fixed index $1\leq i\leq n$ we get the following contribution:
\begin{equation*}
    \mathbb{E}[W_i(t)\cdot \partial_i G(W_1(t),\dots,W_n(t))]\mathbb{E}[Z'_i(t)Z_i(t)].
\end{equation*}
This cancels with the linear part in $\varphi'(t)$ with fixed $i$, namely
\begin{equation*}
    \mathbb{E}[-\mathbb{E}[Z_i(t)Z'_i(t)]W_i(t)\cdot \partial_i G(W_1(t),\dots,W_n(t))].
\end{equation*}

$\bullet$ It remains to consider the case where the other Gaussian variable in the Gaussian integration by parts formula is in $G(W_1(t),\dots,W_n(t))$. For fixed $1\leq i\leq n$, their contribution amounts to
\begin{equation*}
    \sum\limits_{j=1}^{n}\mathbb{E}[W_i(t)W_j(t)\partial_{ij} G(W_1(t),\dots,W_n(t))]\mathbb{E}[Z'_i(t)Z_j(t)].
\end{equation*}
Recalling that 
\begin{equation*}
    \mathbb{E}[Z_i(t)Z'_j(t)]=\frac{1}{2}(\mathbb{E}[B_iB_j]-\mathbb{E}[A_iA_j])
\end{equation*}
and summing over all $1\leq i\leq n$, we have proven that
\begin{equation*}
    \varphi'(t)=\frac{1}{2}\sum\limits_{1\leq i,j\leq n}\mathbb{E}[\partial_{ij}G(W_1(t),\dots,W_n(t))W_i(t)W_j(t)](\mathbb{E}[B_iB_j]-\mathbb{E}[A_iA_j]).
\end{equation*}
This finished the proof of~\eqref{eq:KeyIdentity}.

\label{th:GeneralKahane}
Let $T=\{1,\dots,n\}$ be a discrete index space and $\textbf{A},\textbf{B}$ two centered Gaussian vectors indexed by $T$. Let $G(x_1,\dots,x_n)$ be some real-valued function with subgaussian growth at infinity as well as in all its first and second partial derivatives, and such that for any $(i,j)\in T^2$, we have
\begin{equation}\label{eq:SignCondition}
    (\mathbb{E}[B_iB_j]-\mathbb{E}[A_iA_j])\partial_{ij}G(x_1,\dots,x_n)\geq 0.
\end{equation}
Then with 
\begin{equation*}
    W^{A}_i\coloneqq W_i(0)=\exp\left(A_i-\frac{1}{2}\mathbb{E}[A_i^2]\right),\quad W^{B}_i\coloneqq W_i(1)=\exp\left(B_i-\frac{1}{2}\mathbb{E}[B_i^2]\right),
\end{equation*}
we have
\begin{equation}\label{eq:ConclusionKahane}
    \mathbb{E}[G(W^{A}_1,\dots,W^{A}_n)]\leq\mathbb{E}[G(W^{B}_1,\dots,W^{B}_n)].
\end{equation}

We recall identity~\eqref{eq:KeyIdentity}. When the sign condition~\eqref{eq:SignCondition} is satisfied, for any $(i,j)\in T^2$, the term
\begin{equation*}
    \mathbb{E}[\partial_{ij}G(W_1(t),\dots,W_n(t))W_i(t)W_j(t)](\mathbb{E}[B_iB_j]-\mathbb{E}[A_iA_j])
\end{equation*}
is positive since $W_i(t),W_j(t)$ are positive quantities. Summing up over all $(i,j)\in T^2$ yields the proof of the theorem.

\label{lemm:DecorrelateBulkBoundaryPositiveDistance}
Suppose that $Q$ is a bounded region in $\overline{\mathbb{H}}$ and $I\subset\mathbb{R}$ is a bounded interval on the boundary. Consider the log-correlated Gaussian field $X$ defined with the general covariance kernel~\eqref{eq:GeneralCovarianceKernelHalfPlane} with smooth bounded correction term $g$. Suppose also that for some $p,q>0$,
\begin{equation*}
    \mathbb{E}[\mu^{\mathrm{H}}(Q)^{p}]<\infty\quad\text{and}\quad\mathbb{E}[\mu^{\partial}(I)^{-q}]<\infty.
\end{equation*}
Then for some constant $C$ depending only on $\gamma,Q,I$ and $||g||_{\infty}$,
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q)^{p}}{\mu^{\partial}(I)^{q}}\right]\leq C\mathbb{E}[\mu^{\mathrm{H}}(Q)^{p}]\mathbb{E}[\mu^{\partial}(I)^{-q}].
\end{equation*}

By the boundedness assumptions on $Q,I$ and $g$, we know that there exists some constant $K>0$ depending only on $Q,I$ and $||g||_{\infty}$ such that
\begin{equation*}
    \forall x\in Q, \forall y\in I,\quad\mathbb{E}[X(x)X(y)]\geq -K.
\end{equation*}
Therefore, the field $\widetilde{X}=X+\sqrt{K}N$, where $N$ is an independent standard Gaussian variable, has positive covariance on $Q\times I$. Consequently, if $\widetilde{X_Q}$ and $\widetilde{X_I}$ are independent copies of $\widetilde{X}$ restricted to $Q$ and $I$, we have that
\begin{equation*}
    \forall x\in Q, \forall y\in I,\quad\mathbb{E}[\widetilde{X_Q}(x)\widetilde{X_I}(y)]\leq\mathbb{E}[\widetilde{X}(x)\widetilde{X}(y)]
\end{equation*}
while all the other covariances on $(Q\cup I)^2$ are equal. Applying Theorem~\ref{th:GeneralKahane} yields
\begin{equation*}
    \mathbb{E}\left[\frac{\widetilde{\mu^{\mathrm{H}}}(Q)^{p}}{\widetilde{\mu^{\partial}}(I)^{q}}\right]\leq \mathbb{E}[\widetilde{\mu_Q^{\mathrm{H}}}(Q)^{p}]\mathbb{E}[\widetilde{\mu^{\partial}_I}(I)^{-q}],
\end{equation*}
where $\widetilde{\mu^{\mathrm{H}}}$ and $\widetilde{\mu^{\partial}}$ are the respective bulk and boundary Gaussian multiplicative chaos measures associated to the field $\widetilde{X}$, and $\widetilde{\mu_Q^{\mathrm{H}}}$ and $\widetilde{\mu^{\partial}_I}$ are the respective bulk and boundary Gaussian multiplicative chaos measures associated to the fields $\widetilde{X_Q}$ and $\widetilde{X_I}$. Factorizing out the independent Gaussian factors in all the measures on the left and right hand side in the above display yields the result.

\label{lemm:FinitenessBulkBoundaryGeneralKernel}
Suppose that $Q$ is a bounded region in $\overline{\mathbb{H}}$ and $I\subset\mathbb{R}$ is a bounded interval on the boundary. Consider the log-correlated Gaussian field $X$ defined with the general covariance kernel~\eqref{eq:GeneralCovarianceKernelHalfPlane} with smooth bounded correction term $g$, and the exact scale-invariant log-correlated Gaussian field $X_\mathrm{C}$ with covariance~\eqref{eq:ExactScalingKernel} without the correction term. Then for any $p>1,q>0$, the finiteness of the following expectations are equivalent (in the sense that they differ at most by some positive multiplicative constant)
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q)^{p}}{\mu^{\partial}(I)^{q}}\right]\quad\text{and}\quad\mathbb{E}\left[\frac{\mu^{\mathrm{H}}_{\mathrm{C}}(Q)^{p}}{\mu^{\partial}_{\mathrm{C}}(I)^{q}}\right],
\end{equation*}
where $\mu^{\mathrm{H}}_{\mathrm{C}}$ and $\mu^{\partial}_{\mathrm{C}}$ are the respective bulk and boundary Gaussian multiplicative chaos measure associated to the exact scaling field $X_{\mathrm{C}}$.

In fact, these two expectations are comparable up to a multiplicative constant $C$ that only depends on $\gamma,Q,I$ and $||g||_{\infty}$.

The proof is similar to the one above: we will modify the log-correlated Gaussian fields by adding independent global Gaussian constants.

Consider the following upper bounds of the differences in covariance between $X$ and $X_{\mathrm{C}}$ on different domains:
\begin{equation*}
\begin{split}
    K_Q&=\sup\{z,w\in Q~;~|K(z,w)-K_{\mathrm{C}}(z,w)|\};\\
    K_I&=\sup\{z,w\in I~;~|K(z,w)-K_{\mathrm{C}}(z,w)|\};\\
    K&=\sup\{z,w\in Q\cup I~;~|K(z,w)-K_{\mathrm{C}}(z,w)|\}.
\end{split}
\end{equation*}
Notice that these constants are finite by our boundedness assumptions, and only depend on $Q,I$ and $||g||_{\infty}$.

In view of applying the generalized Kahane's inequality of Theorem~\ref{th:GeneralKahane}, we should make the covariance of $X$ smaller than that of $X_{\mathrm{C}}$ on $Q\times Q$ and $I\times I$, but greater than that of $X_{\mathrm{C}}$ on $Q\times I$. Take then three independent standard Gaussian random variables (also independent of $X$ and $X_{\mathrm{C}}$) denoted $N_Q,N_I,N$ and modify the fields $X$ and $X_{\mathrm{C}}$ in the following manner. Define
\begin{equation*}
\begin{split}
    \widetilde{X}(z)&=X(z)+\sqrt{K}N\mathbf{1}_{\{z\in Q\cup I\}},\\
    \widehat{X_\mathrm{C}}(z)&=X_{\mathrm{C}}(z)+\sqrt{K+K_Q}N_Q\mathbf{1}_{\{z\in Q\}}+\sqrt{K+K_I}N_I\mathbf{1}_{\{z\in I\}}.
\end{split}
\end{equation*}
One verifies that $\widetilde{X}$ and $\widehat{X_{\mathrm{C}}}$ satisfies the comparison of covariances we describe above. Then applying Theorem~\ref{th:GeneralKahane} yields
\begin{equation*}
    \mathbb{E}\left[\frac{\widetilde{\mu^{\mathrm{H}}}(Q)^{p}}{\widetilde{\mu^{\partial}}(I)^{q}}\right]\leq\mathbb{E}\left[\frac{\widehat{\mu^{\mathrm{H}}_{\mathrm{C}}}(Q)^{p}}{\widehat{\mu^{\partial}_{\mathrm{C}}}(I)^{q}}\right],
\end{equation*}
where $\widetilde{\mu^{\mathrm{H}}},\widetilde{\mu^{\partial}}$ are associated to $\widetilde{X}$ and $\widehat{\mu^{\mathrm{H}}_{\mathrm{C}}},\widehat{\mu^{\partial}_{\mathrm{C}}}$ are associated to $\widehat{X_{\mathrm{C}}}$. Factorizing out the independent global Gaussian constant (notice that this only depends on $\gamma,Q,I$ and $||g||_{\infty}$) yields one side of the inequality; the other side is similar.

\label{lemm:finiteness_of_quotients_with_positive_distance}
If a bounded region $A$ of the upper-half plane $\mathbb{H}$ is of some positive distance to $\mathbb{R}$, then
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(A)^{p}}{\mu^{\partial}(\delta A)^{q}}\right]<\infty
\end{equation*}
if and only if $p<\frac{4}{\gamma^2}$ and $-q<\frac{4}{\gamma^2}$.

We can use the generalized Kahane's inequality of Theorem~\ref{th:GeneralKahane} to decorrelate the log-correlated field $X_\mathrm{N}$ restricted to $A$ and to $\delta A$, and this results in
\begin{equation*}
    \frac{1}{C}\mathbb{E}[\mu(A)^{p}]\mathbb{E}\left[\mu^{\partial}(\delta A)^{-q}\right]\leq \mathbb{E}\left[\frac{\mu(A)^{p}}{\mu^{\partial}(\delta A)}\right]\leq C\mathbb{E}[\mu(A)^{p}]\mathbb{E}\left[\mu^{\partial}(\delta A)^{-q}\right]
\end{equation*}
for some finite positive constant $C$. The second inequality is due to Lemma~\ref{lemm:DecorrelateBulkBoundaryPositiveDistance}, and the first inequality follows from similar considerations. More precisely, the positive distance assumption implies that there exists some $K>0$ such that for all $x\in A$ and $y\in I$, we have $\mathbb{E}[X(x)X(y)]\leq K$. Consider independent copies $X_A$ and $X_I$ respectively on $A$ and $I$ of the field $X$, and modify them to $\widetilde{X_A}=X_A+\sqrt{K}N$ and $\widetilde{X_I}=X_I+\sqrt{K}N$ with the same but independent Gaussian $N$. For the field $X$, we also modify it in the following way: let $N_A,N_I$ be other independent Gaussians, if $x\in A$, we define $\widehat{X}(x)=X(x)+\sqrt{K}N_A$, and if $x\in I$, $\widehat{X}(y)=X(y)+\sqrt{K}N_I$. We have this time $\mathbb{E}[\widehat{X}(x)\widehat{X}(y)]\leq\mathbb{E}[\widetilde{X_A}(x)\widetilde{X_I}(y)]$ if $(x,y)\in (A\times I)\cup (I\times A)$ and equal otherwise. Therefore, we get the reversed inequality via the generalized Kahane's inequality of Theorem~\ref{th:GeneralKahane}, following the same lines as in the proof of Lemma~\ref{lemm:DecorrelateBulkBoundaryPositiveDistance}. The lemma follows from classical moment bounds on Gaussian multiplicative chaos measures (for the boundary measure, the parameter is $\frac{\gamma}{2}$ but the covariance is $-2\ln$, resulting in the moment bound $\frac{4}{\gamma^2}$ instead of $\frac{2}{\gamma^2}$).

Denote by
\begin{equation*}
    \overline{\zeta}(p;0)=\left(2+\frac{\gamma^2}{2}\right)p-\gamma^2p^2.
\end{equation*}
Then for any $A\subset Q_r$ and $p\in\mathbb{R}$,
\begin{equation*}
    \mathbb{E}[\mu^{\mathrm{H}}(rA)^{p}]=r^{\overline{\zeta}(p)}\mathbb{E}[\mu^{\mathrm{H}}(A)^{p}].
\end{equation*}

\label{lemm:exact_scaling_relation_for_quotients}
For any $A\subset Q_r$ and $p,q\in\mathbb{R}$,
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(rA)^{p}}{\mu^{\partial}(\delta(rA))^{q}}\right]=r^{\overline{\zeta}(p-\frac{q}{2};0)}\mathbb{E}\left[\frac{\mu^{\mathrm{H}}(A)^{p}}{\mu^{\partial}(\delta A)^{q}}\right].
\end{equation*}

The proof is a straightforward adaptation of the proof of the previous lemma. We include a brief proof since this is not written elsewhere, and refer to~\cite[Lemma~4]{Huang:2023aa} for the details with the $\epsilon$-mollifier and the infinite expectation case.

Recall the following equality in law, consequence of the exact scaling kernel~\eqref{eq:ExactScalingKernel}:
\begin{equation*}
    \{X_\epsilon(z)+\sqrt{-2\ln r}N\}_{z\in Q_r}=\{X_{r\epsilon}(rz)\}_{z\in Q_r}
\end{equation*}
where $N$ is an independent standard Gaussian variable. Applying this to the lemma, we have the following equality in law:
\begin{equation*}
\begin{split}
    \frac{\mu^{\mathrm{H}}(rA)^{p}}{\mu^{\partial}(\delta(rA))^{q}}&=\lim_{\epsilon\to 0}\frac{\left(\int_{rA}e^{\gamma X_{r\epsilon}(z)-\frac{\gamma^2}{2}\mathbb{E}[X_{r\epsilon}(z)^2]}\text{Im}(z)^{-\frac{\gamma^2}{2}}d^2z\right)^{p}}{\left(\int_{\delta (rA)}e^{\frac{\gamma}{2}X_{r\epsilon}(w)-\frac{\gamma^2}{8}\mathbb{E}[X_{r\epsilon}(w)^2]}dw\right)^{q}}\\
    &=\lim_{\epsilon\to 0}\frac{(e^{\gamma\sqrt{-2\ln r}N-\frac{\gamma^2}{2}(-2\ln r)}r^{-\frac{\gamma^2}{2}}r^2)^{p}\cdot\left(\int_{A}e^{\gamma X_{\epsilon}(z)-\frac{\gamma^2}{2}\mathbb{E}[X_\epsilon(z)^2]}\text{Im}(z)^{-\frac{\gamma^2}{2}}d^2z\right)^{p}}{(e^{\frac{\gamma}{2}\sqrt{-2\ln r}N-\frac{\gamma^2}{8}(-2\ln r)}r)^{q}\cdot\left(\int_{\delta A}e^{\frac{\gamma}{2}X_\epsilon(w)-\frac{\gamma^2}{8}\mathbb{E}[X_\epsilon(w)^2]}dw\right)^{q}}\\
    &=e^{\gamma\sqrt{-2\ln r}(p-\frac{q}{2})}\cdot r^{(2+\frac{\gamma^2}{2})(p-\frac{q}{2})}\cdot\frac{\mu^{\mathrm{H}}(A)^{p}}{\mu^{\partial}(\delta A)^{q}}.
\end{split}
\end{equation*}
The claim follows from taking the expectation
\begin{equation*}
    \mathbb{E}\left[e^{\gamma\sqrt{-2\ln r}(p-\frac{q}{2})}\right]=r^{-\gamma^2(p-\frac{q}{2})^2},
\end{equation*}
and the fact that the random variable $N$ is independent of the rest.

\label{lemm:exact_scaling_relation_for_localized_quotients}
For simplicity, we suppose that the measures are localized at $v=0$ (the general case is similar by translation along $\mathbb{R}$). Then for any $A\subset Q_r$ and $p\in\mathbb{R}$,
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}_{v=0}(rA)^{p}}{\mu_{v=0}^{\partial}(\delta(rA))^{q}}\right]=r^{\widetilde{\zeta}(p;q)}\mathbb{E}\left[\frac{\mu^{\mathrm{H}}_{v=0}(A)^{p}}{\mu_{v=0}^{\partial}(\delta A)^{q}}\right],
\end{equation*}
where we define the localized boundary scaling exponent by
\begin{equation}\label{eq:localized_scaling_exponent}
    \widetilde{\zeta}(p;q)=\overline{\zeta}(p-\frac{q}{2};0)-\gamma^2(p-\frac{q}{2})=(2-\frac{\gamma^2}{2})(p-\frac{q}{2})-\gamma^2(p-\frac{q}{2})^2.
\end{equation}

The proof is similar to the one above and details are omitted. By an exact scaling calculation as the previous one we get
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}_{v=0}(rA)^{p}}{\mu_{v=0}^{\partial}(\delta(rA))^{q}}\right]=e^{\gamma\sqrt{-2\ln r}(p-\frac{q}{2})}\cdot r^{(2-\frac{\gamma^2}{2})(p-\frac{q}{2})}\cdot \mathbb{E}\left[\frac{\mu^{\mathrm{H}}_{v=0}(A)^{p}}{\mu_{v=0}^{\partial}(\delta A)^{q}}\right].
\end{equation*}
and the claim follows from the independence of the Gaussian factor $N$.

\label{rema:sign-change}
Notice that the unlocalized/localized scaling exponent functions $\overline{\zeta}(p;q)$ and $\widetilde{\zeta}(p;q)$ are both trivial when $q=2p$. It is also useful to observe the sign-change of $\widetilde{\zeta}(p;q)$:
\begin{enumerate}
    \item When $2p>q$, the function $\widetilde{\zeta}(p;q)$ is positive if and only if $p-\frac{q}{2}<\frac{2}{\gamma^2}-\frac{1}{2}$;
    \item When $2p<q$, the function $\widetilde{\zeta}(p;q)$ is positive if and only if $p-\frac{q}{2}>\frac{2}{\gamma^2}-\frac{1}{2}$.
\end{enumerate}

We will also need the following sign-change of the unlocalized scaling exponent function $\overline{\zeta}(p;q)-1$: this quantity is positive if and only if $p-\frac{q}{2}\in(\frac{1}{2},\frac{2}{\gamma^2})$, with $\gamma\in(0,2)$.

\label{rema:explosion_at_criticality_large_q}
Notice that we have also proven the explosion at the critical threshold $p_c=\frac{4}{\gamma^2}$ in this case. Indeed, first observe that
\begin{equation*}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q)^{p}}{\mu^{\partial}(I)^{q}}\right]\geq \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q^{\mathrm{U}})^{p}}{\mu^{\partial}(I)^{q}}\right]\geq C\mathbb{E}\left[\mu^{\mathrm{H}}(Q^{\mathrm{U}})^{p}\right]\mathbb{E}\left[\mu^{\partial}(I)^{-q}\right]
\end{equation*}
by Lemma~\ref{lemm:finiteness_of_quotients_with_positive_distance}. But $\mathbb{E}\left[\mu^{\mathrm{H}}(Q^{\mathrm{U}})^{p}\right]$ explodes when $p\geq \frac{4}{\gamma^2}$ (and the negative moment of the boundary measure is always non-trivial~\cite[Theorem~2.12]{Rhodes_2014}).

By symmetry, suppose that $v\in[0,r]$ and denote by $\rho=r-v$ the distance from $v$ to the nearest end point $r$. To show Theorem~\ref{th:main_result_positive}, it suffices to prove that, under the corresponding conditions of Theorem~\ref{th:main_result_positive},
\begin{equation}\label{eq:C_1_C_2_delta}
    \mathbb{E}\left[\frac{\mu_v^{\mathrm{H}}(Q)^{p}}{\mu_v^{\partial}(I)^{q+1}}\right]\leq C_1+C_2 \rho^{-\eta_{(p;q+1)}}
\end{equation}
for some coefficient $\eta_{(p;q+1)}>-1$, and $C_1,C_2$ independent of $\rho$, i.e. independent of the position of $v$. Indeed, plugging this bound in the integral~\eqref{eq:deadlyintegral} yields the finiteness of $\mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q)^{p}}{\mu^{\partial}(I)^{q}}\right]$.

\label{lemm:cutecutelemma}
Suppose that the unlocalized $(p,q+1)$-joint moment of the bulk/boundary quotient
\begin{equation}\label{eq:cuteassumption}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q)^{p}}{\mu^{\partial}(I)^{q+1}}\right]<\infty
\end{equation}
is finite and $q<2p-1, p<\frac{4}{\gamma^2}, p<\frac{2}{\gamma^2}+\frac{q}{2}$. Then the integrand above, i.e.
\begin{equation}\label{eq:cuteconclusion}
    \mathbb{E}\left[\frac{\mu_v^{\mathrm{H}}(Q)^{p}}{\mu_v^{\partial}(I)^{q+1}}\right]
\end{equation}
is uniformly bounded in $v\in[-r,r]$.

\label{prop:cute_Gamma}
Suppose that $p<\frac{4}{\gamma^2}$ and~\eqref{eq:cuteassumption} holds. Then
\begin{equation}\label{eq:cute_Gamma}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(\Gamma_{2^{-1}r})^{p}}{\mu^{\partial}(\partial \Gamma_{2^{-1}r})^{q+1}}\right]<\infty.
\end{equation}

Notice that $\Gamma_{2^{-1}r}$ is the union of $Q^{\mathrm{U}}$ and $Q^{\mathrm{L}}$, the ``upper'' and ``lower left'' part of the Carleson cube $Q_r$. Suppose that $0\leq p\leq 1$, then by the subadditivity inequality,
\begin{equation*}
    \left[\frac{\mu^{\mathrm{H}}(\Gamma_{2^{-1}r})^{p}}{\mu^{\partial}(\partial \Gamma_{2^{-1}r})^{q+1}}\right]\leq \left[\frac{\mu^{\mathrm{H}}(Q^{\mathrm{L}})^{p}}{\mu^{\partial}(\partial \Gamma_{2^{-1}r})^{q+1}}\right]+\left[\frac{\mu^{\mathrm{H}}(Q^{\mathrm{U}})^{p}}{\mu^{\partial}(\partial \Gamma_{2^{-1}r})^{q+1}}\right].
\end{equation*}
But Lemma~\ref{lemm:exact_scaling_relation_for_quotients} implies that the first term is
\begin{equation*}
    \left[\frac{\mu^{\mathrm{H}}(Q^{\mathrm{L}})^{p}}{\mu^{\partial}(\delta Q^{\mathrm{L}})^{q}}\right]=2^{-\overline{\zeta}(p;q+1)}\mathbb{E}\left[\frac{\mu^{\mathrm{H}}(Q)^{p}}{\mu^{\partial}(I)^{q+1}}\right]<\infty
\end{equation*}
by assumption~\eqref{eq:cuteassumption}, and the second term is finite when $p<\frac{4}{\gamma^2}$ by Lemma~\ref{lemm:finiteness_of_quotients_with_positive_distance}.

When $p>1$, replace the subadditivity inequality by Minkowski's inequality for the $L_p$-norm which yields
\begin{equation*}
    \left[\frac{\mu^{\mathrm{H}}(\Gamma_{2^{-1}r})^{p}}{\mu^{\partial}(\partial \Gamma_{2^{-1}r})^{q+1}}\right]^{\frac{1}{p}}\leq \left[\frac{\mu^{\mathrm{H}}(Q^{\mathrm{L}})^{p}}{\mu^{\partial}(\partial \Gamma_{2^{-1}r})^{q+1}}\right]^{\frac{1}{p}}+\left[\frac{\mu^{\mathrm{H}}(Q^{\mathrm{U}})^{p}}{\mu^{\partial}(\partial \Gamma_{2^{-1}r})^{q+1}}\right]^{\frac{1}{p}}.
\end{equation*}
The same conclusion thus follows.

\label{prop:cute_Pi}
If $p<\frac{4}{\gamma^2}$ and~\eqref{eq:cuteassumption} holds. Then
\begin{equation}\label{eq:cute_Pi}
    \mathbb{E}\left[\frac{\mu^{\mathrm{H}}(\Pi_r)^{p}}{\mu^{\partial}(\delta\Pi_r)^{q+1}}\right]<\infty
\end{equation}

\label{prop:Improved_cute_Gamma}
Suppose that~\eqref{eq:cuteassumption} holds. Then following supremum over the the localized $(p,q+1)$-joint moments is finite: 
\begin{equation}\label{eq:uniformly_cute_Gamma}
    \sup_{d\in[\frac{r}{4},\frac{r}{2}]}\mathbb{E}\left[\frac{\mu_r^{\mathrm{H}}(Q_r\setminus Q'_{d})^{p}}{\mu^{\partial}_r(\partial (Q_r\setminus Q'_{d}))^{q+1}}\right]<\infty
\end{equation}
if $q<2p-1, p<\frac{4}{\gamma^2}, p<\frac{2}{\gamma^2}+\frac{q}{2}$.

The proof is almost identical to that of Proposition~\ref{prop:cute_Gamma}. Notice that (see Figure~\ref{fig:Improved_Gamma}) 
\begin{equation*}
    Q_r\setminus Q'_{d}\subset \left([-r,2r-2d]\times [0,r-2d]\right)\cup \left([-r,r]\times [\frac{r}{2},2r]\right).
\end{equation*}

